async function logoCmd(args) {
  const query = args._.join(" ").trim();
  if (!query) {
    console.error(
      "Usage: 21st logo <query> [--limit N] [--json]   (search brand + UI SVG logos)"
    );
    process.exit(1);
  }
  const limit = typeof args.flags.limit === "string" ? Number(args.flags.limit) : 12;
  let items = [];
  try {
    const res = await fetch(
      `https://api.svgl.app?search=${encodeURIComponent(query)}`,
      { headers: { Accept: "application/json" } }
    );
    if (res.status !== 404) {
      if (!res.ok) throw new Error(`logo search responded ${res.status}`);
      const data = await res.json();
      if (Array.isArray(data)) items = data;
    }
  } catch (e) {
    console.error(
      `Logo search failed: ${e instanceof Error ? e.message : String(e)}`
    );
    process.exit(1);
  }
  const capped = items.slice(0, Number.isFinite(limit) ? limit : 12);
  if (args.flags.json) {
    console.log(JSON.stringify(capped, null, 2));
    if (!capped.length) process.exit(1);
    return;
  }
  if (!capped.length) {
    console.error(`No logos found for "${query}".`);
    process.exit(1);
  }
  for (const it of capped) {
    const route = it.route;
    const light = typeof route === "string" ? route : route?.light ?? route?.dark ?? "";
    const darkUrl = typeof route === "object" && route?.dark && route.dark !== route.light ? route.dark : "";
    console.log(it.title ?? "(untitled)");
    if (light) console.log(`  ${light}`);
    if (darkUrl) console.log(`  ${darkUrl}  (dark)`);
  }
  console.log("\nGrab one: curl -O <url>");
}
