  if (!user || !slug || extra.length) {
    console.error(
      "Usage: 21st add <user>/<slug> [--print]  (e.g. 21st add shadcn/button)\n       21st add @<registry> [--print]  (e.g. 21st add @limeplay) installs a whole registry"
    );
    process.exit(1);
  }
